-- ISO countries
-- public.countries: SELECT
SELECT id, name, iso_code
FROM public.countries;

-- public.countries: SELECT by key
SELECT id, name, iso_code
FROM public.countries
WHERE id = :id;

-- public.countries: INSERT
INSERT INTO public.countries (name, iso_code)
VALUES (:name, :iso_code)
RETURNING id;

-- public.countries: UPDATE
UPDATE public.countries
SET
    name = :name,
    iso_code = :iso_code
WHERE id = :id;

-- public.countries: DELETE
DELETE FROM public.countries
WHERE id = :id;

-- public.countries: UPSERT
INSERT INTO public.countries (id, name, iso_code)
OVERRIDING SYSTEM VALUE
VALUES (:id, :name, :iso_code)
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    iso_code = EXCLUDED.iso_code;

